def longest_arithmetic_subsequence(nums):
 dp=[{} for _ in nums];answer=2
 for j in range(len(nums)):
  for i in range(j):
   difference=nums[j]-nums[i];dp[j][difference]=dp[i].get(difference,1)+1;answer=max(answer,dp[j][difference])
 return answer

